window.products.push({"id":1128519,"name":"Zojirushi Stainless Steel Thermal Vacuum Cooking Pot, 1-1/2-Gallon","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81TUkohD8VL._AC_SL1500_.jpg","description":"Our 1-1/2-Gallon stainless steel thermal vacuum cooking pot works like a non electric slow cooker. The Vacuum insulated outer container keeps the heat inside to complete cooking foods using their own heat for energy efficient slow cooking. The glass lid allows you to watch the heating process. Stay cool side handles enable you safely handle the cooking pot. This unit saves energy and reduces cooking costs.","images":["https://m.media-amazon.com/images/I/81TUkohD8VL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Zojirushi","source_asin":"B004P45ZB6","category_path":"Home & Kitchen"},"sku":"BM-1128519","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B004P45ZB6","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B004P45ZB6","price_pending":true,"merchant_ready":false});
